/// Host -> Flutter. One instance per platform view, keyed by view id.
///
/// Generated protocol from Pigeon that represents Flutter messages that can be called from Swift.
@objc protocol MapKitFlutterApiBridge {
  @objc func onCameraMoveStarted(error: MapKitHostError)
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onCameraMove(pigeonVar_args: NSData, error: MapKitHostError)
  @objc func onCameraIdle(error: MapKitHostError)
  /// `MKMapViewDelegate.mapView(_:didChange:animated:)` — e.g. MapKit drops
  /// to `none` when the user pans.
  @objc func onUserTrackingModeChanged(mode modeArg: Int64, error: MapKitHostError)
  /// `MKMapViewDelegate.mapView(_:didSelect:)` for a Flutter annotation.
  @objc func onAnnotationSelect(annotationId annotationIdArg: NSString, error: MapKitHostError)
  /// `MKMapViewDelegate.mapView(_:didDeselect:)` for a Flutter annotation.
  @objc func onAnnotationDeselect(annotationId annotationIdArg: NSString, error: MapKitHostError)
  /// A selected `MKMapFeatureAnnotation` (iOS).
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onMapFeatureSelected(pigeonVar_args: NSData, error: MapKitHostError)
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onAnnotationDragStart(annotationId annotationIdArg: NSString, pigeonVar_args: NSData, error: MapKitHostError)
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onAnnotationDragEnd(annotationId annotationIdArg: NSString, pigeonVar_args: NSData, error: MapKitHostError)
  @objc func onCalloutTap(annotationId annotationIdArg: NSString, error: MapKitHostError)
  @objc func onPolylineTap(polylineId polylineIdArg: NSString, error: MapKitHostError)
  @objc func onPolygonTap(polygonId polygonIdArg: NSString, error: MapKitHostError)
  @objc func onCircleTap(circleId circleIdArg: NSString, error: MapKitHostError)
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onMapTap(pigeonVar_args: NSData, error: MapKitHostError)
  // swift-format-ignore: AlwaysUseLowerCamelCase
  @objc func onMapLongPress(pigeonVar_args: NSData, error: MapKitHostError)
  /// `MKMapViewDelegate.mapViewDidFailLoadingMap(_:withError:)`.
  @objc func onDidFailLoadingMap(error errorArg: NSString, error: MapKitHostError)
  /// `MKMapViewDelegate.mapView(_:didFailToLocateUserWithError:)`.
  @objc func onDidFailToLocateUser(error errorArg: NSString, error: MapKitHostError)
}

@objc class MapKitFlutterApiRegistrar: NSObject {
  static var registeredMapKitFlutterApi = [String: [MapKitFlutterApi]]()
  /// Guards the registrations, which Native Interop calls can read from any thread.
  static let lock = NSLock()

  /// Registers the Dart implementation `api` under `name` (or the default instance
  /// when `name` is omitted).
  ///
  /// Called by generated Dart code. `engineId` and `affinityKey` identify the engine
  /// that registered `api`, or are `Int64.min` when unknown.
  /// Registering an instance that is already registered under `name` updates its
  /// keys and keeps its position.
  @objc static func registerInstance(api: MapKitFlutterApiBridge, engineId: Int64, affinityKey: Int64, name: String = MessagesPigeonInternal.defaultInstanceName) {
    let apiObject = api as AnyObject
    MapKitFlutterApiRegistrar.lock.lock()
    defer { MapKitFlutterApiRegistrar.lock.unlock() }
    var list = MapKitFlutterApiRegistrar.registeredMapKitFlutterApi[name] ?? []
    let registration = MapKitFlutterApi(api: api, engineId: engineId, affinityKey: affinityKey)
    if let index = list.firstIndex(where: { ($0.api as AnyObject) === apiObject }) {
      list[index] = registration
    } else {
      list.append(registration)
    }
    MapKitFlutterApiRegistrar.registeredMapKitFlutterApi[name] = list
  }

  /// Removes `api` from the registrations under `name` (or the default instance
  /// when `name` is omitted), leaving other registrations in place.
  ///
  /// Instances are matched by identity. Does nothing if `api` is not registered.
  @objc static func unregisterInstance(api: MapKitFlutterApiBridge, name: String = MessagesPigeonInternal.defaultInstanceName) {
    let apiObject = api as AnyObject
    // Removed entries are kept alive until after unlocking so their deinit cannot run while the
    // non-recursive lock is held.
    var displaced: [MapKitFlutterApi] = []
    do {
      MapKitFlutterApiRegistrar.lock.lock()
      defer { MapKitFlutterApiRegistrar.lock.unlock() }
      guard var list = MapKitFlutterApiRegistrar.registeredMapKitFlutterApi[name] else {
        return
      }
      list.removeAll { entry in
        if (entry.api as AnyObject) === apiObject {
          displaced.append(entry)
          return true
        }
        return false
      }
      if list.isEmpty {
        MapKitFlutterApiRegistrar.registeredMapKitFlutterApi.removeValue(forKey: name)
      } else {
        MapKitFlutterApiRegistrar.registeredMapKitFlutterApi[name] = list
      }
    }
    withExtendedLifetime(displaced) {}
  }

  #if canImport(Flutter) || canImport(FlutterMacOS)
    /// Returns the instance for `name` (or the default instance when `name` is omitted)
    /// that was registered from the engine that owns `registrar`.
    ///
    /// When no instance is known to belong to that engine, falls back to the most
    /// recent registration for `name`. Returns nil if none is registered.
    static func getInstance(registrar: FlutterPluginRegistrar, name: String = MessagesPigeonInternal.defaultInstanceName) -> MapKitFlutterApi? {
      return getInstance(engineKey: PigeonEngineKeys.key(for: registrar), name: name)
    }
  #endif

  fileprivate static func getInstance(engineKey: Int64, name: String) -> MapKitFlutterApi? {
    MapKitFlutterApiRegistrar.lock.lock()
    defer { MapKitFlutterApiRegistrar.lock.unlock() }
    guard let list = MapKitFlutterApiRegistrar.registeredMapKitFlutterApi[name] else {
      return nil
    }
    if engineKey != Int64.min, let match = list.last(where: { $0.engineId == engineKey }) ?? list.last(where: { $0.affinityKey == engineKey }) {
      return match
    }
    return list.last
  }
}

